class Todo {
    private int id;
    private String judul;
    private boolean selesai;
}

interface TodoRepository {
    List<Todo> semua();
}

class TodoRepositoryMemori implements TodoRepository {
    private final List<Todo> data = new ArrayList<>();

    TodoRepositoryMemori(Todo... awal) {
        data.addAll(Arrays.asList(awal));
    }

    public List<Todo> semua() {
        return data;
    }
}

@RequiredArgsConstructor
class TodoService {
    private final TodoRepository repo;
    private int dipanggil;

    int jumlah() {
        dipanggil++;
        return repo.semua().size();
    }
}

