import java.util.*;

import lombok.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Kurir k = new Kurir(new Tarif(Integer.parseInt(in.nextLine().trim())));
        while (in.hasNextLine()) {
            int kilo = Integer.parseInt(in.nextLine().trim());
            System.out.println(kilo + " kg: " + k.ongkos(kilo));
        }
    }
}

@Getter
@AllArgsConstructor
class Tarif {
    private final int perKilo;
}

@RequiredArgsConstructor
class Kurir {
    private final Tarif tarif;

    int ongkos(int kilo) {
        return tarif.getPerKilo() * kilo;
    }
}
